/* applyI18n(lang): swaps every tagged string; missing or empty keys fall back to English. */
window.applyI18n = function (lang) {
  var d = window.I18N[lang] || {}, en = window.I18N.en;
  function t(k) { return d[k] ? d[k] : en[k]; }
  document.querySelectorAll('[data-i18n]').forEach(function (el) { var v = t(el.dataset.i18n); if (v != null) el.innerHTML = v; });
  document.querySelectorAll('[data-i18n-alt]').forEach(function (el) { var v = t(el.dataset.i18nAlt); if (v != null) el.alt = v; });
  document.querySelectorAll('[data-i18n-aria]').forEach(function (el) { var v = t(el.dataset.i18nAria); if (v != null) el.setAttribute('aria-label', v); });
  document.documentElement.lang = lang;
};
